  "matrix_id": "vec-vs-kw-2026-q3",
  "sources": [
    {
      "citation_key": "BM25-baseline",
      "venue_year": "2009",
      "claim_count": 3,
      "findings_used": [
        "Establishes the classical scoring function; reports that IDF-based term weighting remains competitive on clean keyword-matched corpora;",
        "documents failure modes on vocabulary mismatch, estimating relevance drops sharply when query and document share no surface terms."
      ]
    },
    {
      "citation_key": "DPR-2020",
      "venue_year": "2020",
      "claim_count": 3,
      "findings_used": [
        "Reports top-20 retrieval accuracy 78.4 on Natural Questions versus 59.1 for BM25;",
        "notes dense retrieval underperforms BM25 on out-of-domain entity-heavy queries;",
        "training required 100k+ labeled question-passage pairs."
      ]
    },
    {
      "citation_key": "BEIR-2021",
      "venue_year": "2021",
      "claim_count": 4,
      "findings_used": [
        "Evaluates 18 retrieval systems across 18 datasets; finds BM25 surprisingly strong zero-shot median nDCG@10 of 41.9;",
        "most dense models trained on MS MARCO fail to consistently beat it out-of-domain;",
        "concludes domain shift is the dominant failure axis for learned retrieval.";
        "BM25 performs well in zero-shot settings across diverse domains."
      ]
    },
    {
      "citation_key": "Hybrid-2022",
      "venue_year": "2022",
      "claim_count": 3,
      "findings_used": [
        "Reports a router combining BM25 and dense candidates beats both standalone systems on a mixed in-domain/out-of-domain workload, relative improvement 7-11% nDCG@10 over the better single system;",
        "routing errors concentrated on short queries under four terms.";
        "hybrid routing improves performance across domain shifts."
      ]
    },
    {
      "citation_key": "ANN-cost-2021",
      "venue_year": "2021",
      "claim_count": 3,
      "findings_used": [
        "Engineering study of approximate nearest neighbor indexes: recall@1 above 0.95 achievable at sub-10-millisecond latency for 100M vectors on a single GPU;",
        "index build and memory cost scale linearly with corpus size;",
        "retraining embeddings requires full reindex."
      ]
    },
    {
      "citation_key": "Rerank-2023",
      "venue_year": "2023",
      "claim_count": 2,
      "findings_used": [
        "Shows cross-encoder reranking of top-100 candidates lifts end accuracy substantially, at the cost of one LLM inference per candidate;",
        "authors recommend reranking only when first-stage precision is already adequate."
      ]
    }
  ],
  "themes": [
    {
      "theme_name": "domain-shift robustness",
      "supporting_keys": [
        "BEIR-2021",
        "DPR-2020"
      ],
      "synthesis": "The evidence supports that dense retrieval is vulnerable to domain shift, as BEIR-2021 finds BM25 outperforms most dense models in zero-shot settings and identifies domain shift as the dominant failure axis. DPR-2020 notes dense retrieval underperforms BM25 on entity-heavy out-of-domain queries. However, BEIR-2021 also observes that BM25's performance is surprisingly strong in zero-shot settings across domains, suggesting it may be more robust than dense models in closed-domain scenarios with domain shift. The pack does not evaluate internal wiki corpora or codename-heavy query distributions specifically, so the applicability to our use case remains unverified.",
